<?php
declare(strict_types=1);namespace Pam\Native\Widgets;use InvalidArgumentException;final readonly class WidgetContent{public function __construct(public string$title,public string$subtitle='',public string$value='',public string$deepLink=''){if(strlen($title)>128||strlen($subtitle)>256||strlen($value)>128)throw new InvalidArgumentException('Widget text exceeds its safe limit.');if($deepLink!==''&&(!preg_match('/^[a-z][a-z0-9+.-]*:\/\//iD',$deepLink)||strlen($deepLink)>2048))throw new InvalidArgumentException('Invalid widget deep link.');}public function payload():array{return['title'=>$this->title,'subtitle'=>$this->subtitle,'value'=>$this->value,'deepLink'=>$this->deepLink,'updatedAtMillis'=>(int)floor(microtime(true)*1000)];}}
